head.script:
// 테스트 설명, 유효성 값 설정
//  ★ 본 샘플은 _1(fixedColumn=왼쪽 고정)과 분리하여 'fixedRightColumn 으로 고정된 Column 영역' 에도 병합이 적용되는지를 검증한다.
//     (description 은 _1 과 동일 유지, validation 은 적용 영역 항목만 유지)
scwin.tData = {
    "description" : "[gridView > P > mergeCellsFixedCols]<br/>Body 의 고정 Column 영역에서 동일한 값이 연속되는 Cell 을 자동으로 병합하는 방식을 설정합니다.",
    "validation" : [
        "fixedRightColumn 으로 고정된 Column 영역에 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 비고정 영역(col1,col2) 과 오른쪽 고정 영역(col3,col4) 의 병합 차이를 보여주도록 구성.
//  [비고정 : col1, col2]  ← 동일값이 연속돼도 병합되면 안 됨(영역 밖)
//  · col1(비고정) : A,A,B,B          → 세로로 동일값이 연속되지만 비고정이라 미병합
//  · col2(비고정) : X,X,X,X          → 전부 동일값이지만 비고정이라 미병합
//  [오른쪽 고정 : fixedRightColumn=2] ← 이 영역의 병합 적용을 검증
//  · col3(우고정) : G,G,H,H          → 세로(bycol) [0~1]=G / [2~3]=H, 행0 에서 col4 와 가로 동일값
//  · col4(우고정) : G,K,K,L          → 세로(bycol) [1~2]=K, 행0 col3=col4=G 가로(byrow) 병합 검증용
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "X", "col3": "G", "col4": "G" },
    { "col1": "A", "col2": "X", "col3": "G", "col4": "K" },
    { "col1": "B", "col2": "X", "col3": "H", "col4": "K" },
    { "col1": "B", "col2": "X", "col3": "H", "col4": "L" }
];



// comp 생성 : fixedRightColumn=2 (col3,col4 우측 고정) 그리드 1개를 동적 생성한다. (fixedColumn=0 → 왼쪽 고정 없음, col1·col2 비고정)
//  ★ mergeCellsFixedCols 는 생성 attribute 로 주지 않고, 데이터 적재+렌더 후 mergeCellsFixedCols() 메소드로 적용한다.
//     (초기 렌더 중 세로병합하면 흡수 Row 가 height 0 으로 collapse 되는 현상 회피 + @spec 동일 이름 메소드 입증)
//  ★ con 미설정('') 이면 메소드를 호출하지 않음(기본 never).
//  ★ 컬럼 폭 합(440)이 그리드 폭(300)보다 크게 하여 가로 스크롤이 생기도록 함 → col3,col4 가 오른쪽에 고정되는 것을 확인.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // con_ 설정값 수집 : '' 미설정(메소드 미호출=기본 never) / never / bycol / byrow
    let vMerge = con_mergeCellsFixedCols.getValue();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCellsFixedCols=' + (vMerge === '' ? '(미설정)' : vMerge) + ' / fixedRightColumn=2 (col3,col4 우측 고정), col1·col2=비고정. 우측 고정 영역만 병합되고 비고정 영역(col1,col2)은 미병합"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedRightColumn=2 로 오른쪽 2개 컬럼(col3,col4) 고정 (fixedColumn 미지정=0)
    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id, fixedRightColumn: 2 });

    // target 생성 (mergeCellsFixedCols 속성은 부여하지 않음 → 아래에서 메소드로 적용)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:300px;height:235px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedCols sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="col1(비고정)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="col2(비고정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3(우고정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4(우고정)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 생성(데이터 적재 완료) 후 mergeCellsFixedCols() 메소드로 병합 적용 (미설정 시 미호출=기본 never)
    if (vMerge !== '') {
        let grid = $p.getComponentById("target1");
        grid.mergeCellsFixedCols(vMerge);
    }
}



// 병합 상태 확인 : 우고정 영역(col3,col4) 의 병합과 비고정 영역(col1,col2) 의 미병합을 직관 출력(⬇세로/➡가로)
//  - 우고정 영역 td 는 _fixedRightColumnDiv 안에 위치하며 id 는 target1_cell_{row}_{col} 형태(scroll 영역과 중복 id 가능)
//  - 화면에 표시되는(흡수되지 않은) td 만 대상으로 rowSpan/colSpan 을 읽어 판정
//  - 영역 판정 : 전체 컬럼수(colCnt) - fixedRightColumn 이상 colIndex = 우고정, 미만 = 비고정
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let gid = target1.id;
    let fixedR = target1.options.fixedRightColumn;   // 오른쪽 고정 컬럼 수 (2)
    let colCnt = target1.getColumnCount();           // 전체 컬럼 수 (4)
    bottom.setReturnValue("[옵션] mergeCellsFixedCols : " + target1.options.mergeCellsFixedCols + " / fixedRightColumn : " + fixedR);

    // colIndex 가 (colCnt - fixedR) 이상이면 우고정, 미만이면 비고정
    let region = function (c) {
        return (c >= colCnt - fixedR) ? "우고정" : "비고정";
    };

    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let rightMerged = false, nonFixedMerged = false;
    let seen = {};
    let descs = [];

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        if (rs > 1 || cs > 1) {
            // 우고정 영역은 td 가 중복 렌더될 수 있으므로 좌표 기준 중복 제거
            let key = r + "_" + c;
            if (seen[key]) continue;
            seen[key] = true;

            let reg = region(c);
            if (reg === "우고정") rightMerged = true;
            else nonFixedMerged = true;

            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ [" + reg + "] col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ [" + reg + "] 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [" + reg + "] [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let mode;
    if (rowSpanCnt === 0 && colSpanCnt === 0) mode = "never (병합 없음)";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) mode = "bycol (세로 병합)";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) mode = "byrow (가로 병합)";
    else mode = "혼합";

    bottom.setReturnValue("판정 : " + mode + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
    bottom.setReturnValue("우고정(col3,col4) 영역 병합 여부 : " + rightMerged + " (fixedRightColumn 영역도 병합 적용됨)");
    bottom.setReturnValue("비고정(col1,col2) 영역 병합 여부 : " + nonFixedMerged + " (false 면 비고정 영역 미병합 → 고정 영역에만 적용)");
}
